{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "AZD3759, a structurally related heteroaromatic kinase inhibitor, achieved Kp,uu,brain of 1.3 in preclinical models, demonstrating that this chemotype can have robust CNS access despite high molecular weight and lipophilicity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In humans, AZD3759 showed approximately 1:1 CSF-to-plasma concentration, directly confirming meaningful CNS penetration for a related quinazoline/aminoheteroaryl inhibitor.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "The highest-similarity analogue had Kpuu,brain of 0.47 and Kpuu,CSF of 0.76 in rats and was classified as good penetration, indicating meaningful unbound brain exposure is achievable in this series.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Another high-similarity analogue had Kpuu,brain of 0.34 and Kpuu,CSF of 0.52 in rats and was also classified as good brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Vorasidenib, a brain-penetrant agent with CF3 and heteroaromatic features, showed a brain tumor-to-plasma concentration ratio of 1.69 in humans, supporting CNS access for lipophilic heteroaromatic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lapatinib, a lower-similarity TKI, is a P-gp/ABCG2 substrate with low brain concentrations, providing a cautionary contradictory example for efflux-prone lipophilic heteroaromatics.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass. The highest-transfer experimental analogues are direct in vivo CNS-penetration measurements (Kpuu,brain 0.34-1.3, human CSF/plasma ~1) in the same general kinase-inhibitor heteroaromatic chemotype, outweighing the uncertain physicochemical prior. The main contradictory lapatinib evidence is lower-transfer and its failure is specifically transporter-mediated; query efflux is only inferred. Overall meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct query-specific PK or BBB data are available.",
    "Morgan similarities are modest (~0.19-0.21), limiting exact structural transfer.",
    "The N-oxide group's metabolic reduction and transporter liability are unmeasured.",
    "High logD may increase plasma protein binding, but unbound brain exposure was not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

